<?php
namespace App\Http\Controllers\Admin;use App\Http\Controllers\Controller;use App\Models\Department;use Illuminate\Http\Request;use Illuminate\Support\Str;use Illuminate\Support\Facades\Storage;
class DepartmentController extends Controller{public function index(){return view('admin.catalog.index',['title'=>'Отделения','route'=>'departments','items'=>Department::orderBy('sort')->get()]);}public function create(){return view('admin.catalog.department',['item'=>new Department]);}public function store(Request $r){Department::create($this->data($r));return redirect()->route('admin.departments.index')->with('ok','Отделение создано');}public function edit(Department $department){return view('admin.catalog.department',['item'=>$department]);}public function update(Request $r,Department $department){$old=$department->image;$d=$this->data($r,$department);$department->update($d);if(isset($d['image'])&&$old&&$old!==$d['image'])Storage::disk('public')->delete($old);return redirect()->route('admin.departments.index')->with('ok','Сохранено');}public function destroy(Department $department){if($department->image)Storage::disk('public')->delete($department->image);$department->delete();return back()->with('ok','Отделение удалено');}private function data(Request $r,?Department $item=null){$d=$r->validate(['name'=>'required|max:255','lead'=>'nullable|max:1000','head'=>'nullable|max:255','description'=>'nullable','image'=>'nullable|image|max:10240','sort'=>'nullable|integer']);$base=Str::slug($r->input('slug')?:$d['name'])?:'department';$slug=$base;$i=2;while(Department::where('slug',$slug)->when($item,fn($q)=>$q->where('id','!=',$item->id))->exists())$slug=$base.'-'.$i++;$d['slug']=$slug;if($r->hasFile('image'))$d['image']=$r->file('image')->store('departments','public');$d['is_active']=$r->boolean('is_active');return $d;}}